    max-height: 45vh !important; /* 从40vh调整为45vh，稍高一点 */
    overflow-y: auto !important;
    overflow-x: hidden !important;
}

/* 2. 优化滚动条体验 */
.chat-container > div > div:last-child .markdown-body details[open] > div {
    scroll-behavior: smooth !important;
}

/* 3. 防止内容过长破坏布局 */
.chat-container > div > div:last-child .markdown-body details[open] > div > * {
    max-width: 100% !important;
    word-break: break-word !important;
}

/* 4. 确保滚动条出现时右侧有足够空间 */
.chat-container > div > div:last-child .markdown-body details[open] > div {
    padding-right: 12px !important; /* 为滚动条留出更多空间 */
    box-sizing: border-box !important;
}

