.chat-container > div > div:last-child .markdown-body details:not([open]) > summary {
    white-space: nowrap !important; /* 防止文字换行 */
    overflow: hidden !important;
    text-overflow: ellipsis !important; /* 如果文字太长，显示省略号 */
}

/* 6. 调整折叠状态的最小宽度，确保文字完全展示 */
.chat-container > div > div:last-child .markdown-body details {
    min-width: 50px !important; /* 增加最小宽度确保文字展示 */
}

