.chat-container > div > div:last-child .markdown-body details[open] > div {
    /* 强制显示滚动条，即使内容不多 */
    overflow-y: scroll !important;

    /* 确保滚动条轨道可见 */
    scrollbar-track-color: rgba(141, 110, 99, 0.1) !important;

    /* 强制Webkit显示滚动条 */
    -webkit-overflow-scrolling: touch !important;
}

/* 8. 确保滚动条始终可见（Webkit浏览器） */
.chat-container > div > div:last-child .markdown-body details[open] > div::-webkit-scrollbar {
    -webkit-appearance: none !important;
    appearance: none !important;
}

.chat-container > div > div:last-child .markdown-body details[open] > div::-webkit-scrollbar:vertical {
    width: 8px !important;
}

/* 9. 确保Firefox显示滚动条 */
@supports (-moz-appearance:none) {
    .chat-container > div > div:last-child .markdown-body details[open] > div {
        overflow-y: scroll !important;
        scrollbar-width: thin !important;
    }
}
/* ================================================= */
/* == 修复重点一：侧边栏滚动条 (强制生效版) == */
/* ================================================= */

/* 1. 限制内容区域高度，强制溢出产生滚动条 */
.chat-container > div > div:last-child .markdown-body details[open] > div {
    max-height: 60vh !important; /* 限制高度为屏幕的60%，留出空间 */
    overflow-y: auto !important; /* 必须：垂直滚动 */
    overflow-x: hidden !important; /* 禁止水平滚动 */
    display: block !important; /* 确保盒子模型正确 */
    padding-right: 15px !important; /* 给滚动条留位置 */
    overscroll-behavior: contain !important; /* 防止滚动时带动背景 */

    /* 视觉边框，辅助确认区域 */
    border-top: 1px dashed rgba(141, 110, 99, 0.3) !important;
    border-bottom: 1px dashed rgba(141, 110, 99, 0.3) !important;
}

/* 2. Webkit浏览器 (Chrome, Edge, Safari) 滚动条美化 - 加粗加深 */
.chat-container > div > div:last-child .markdown-body details[open] > div::-webkit-scrollbar {
    width: 10px !important; /* 加宽，确保容易点中 */
    display: block !important;
}

.chat-container > div > div:last-child .markdown-body details[open] > div::-webkit-scrollbar-track {
    background: rgba(62, 39, 35, 0.1) !important; /* 轨道颜色 */
    border-radius: 4px !important;
