    border-radius: 6px !important;
    box-shadow: 
        0 0 0 3px #fdf5e6, /* 外圈白边，增加层次 */
        0 0 0 5px #5d4037, /* 外圈深褐边 */
        -10px 10px 30px rgba(0, 0, 0, 0.6) !important; /* 强烈的浮空阴影 */

