}

/* 扇轴大宝石 */
#ai-send-button::after {
    content: "" !important;
    position: absolute !important;
    width: 10px !important;
    height: 10px !important;
    background: #8B0000 !important;
    bottom: 5px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    border-radius: 50% !important;
    border: 1.5px solid #c5a059 !important;
    box-shadow: 0 0 10px #8B0000 !important;
    z-index: 3;
}

/* --- 3. 加载/停止按钮：巨型乌木描金扇 (合拢态) --- */
/* 核心修复：精准锁定加载中的黑色圆钮 */
div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer,
.chat-container div[class*="bg-black"].rounded-full {
    background: transparent !important; 
    width: 28px !important; /* 合拢后宽度变窄 */
    height: 70px !important; /* 合拢后高度增加，体现巨扇规格 */
    border-radius: 0 !important;
    position: relative !important;
    overflow: visible !important;
    margin-left: 15px !important;
    box-shadow: none !important;
}

/* 隐藏正方形停止图标 */
div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer svg {
    display: none !important;
}

/* 绘制合拢状态的巨扇扇骨 */
div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer::before,
.chat-container div[class*="bg-black"].rounded-full::before {
    content: "" !important;
    position: absolute !important;
    width: 18px !important; /* 更加厚重的扇身 */
    height: 65px !important;
    bottom: 5px !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    /* 乌木质感 + 金丝缠绕纹路 */
    background: 
        linear-gradient(to right, #2c241b 0%, #4e342e 50%, #1a1a1a 100%),
        repeating-linear-gradient(180deg, transparent 0, transparent 10px, rgba(197,160,89,0.3) 10px, rgba(197,160,89,0.3) 11px) !important;
    border: 2px solid #c5a059 !important;
    border-radius: 4px 4px 8px 8px !important;
    box-shadow: 5px 5px 15px rgba(0,0,0,0.5) !important;
    z-index: 10;
}

/* 合扇顶部的描金装饰 */
div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer::after,
.chat-container div[class*="bg-black"].rounded-full::after {
    content: "" !important;
    position: absolute !important;
    width: 4px !important;
    height: 25px !important;
    background: linear-gradient(to bottom, #8B0000, #4a0000) !important; /* 垂下的长红缨 */
    top: 90% !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    box-shadow: 0 0 10px #8B0000 !important;
