.inline-block div.group.flex.items-center.justify-center.w-8.h-8.mr-1 {
    background: #fdfaf2 !important; 
    background-image: radial-gradient(circle at 30% 30%, #ffffff 0%, #fdfaf2 100%) !important;
    border: 1.5px solid #d4b170 !important;
    border-radius: 6px 6px 4px 4px !important;
    width: 32px !important; 
    height: 42px !important;
    position: relative !important;
    margin-right: 0px !important;
    box-shadow: 
        inset 0 0 8px rgba(255, 255, 255, 0.8),
        2px 2px 5px rgba(0,0,0,0.1) !important;
    transition: all 0.2s ease !important;
    z-index: 2;
}

.inline-block div.group.flex.items-center.justify-center.w-8.h-8.mr-1 svg {
    display: none !important;
}

.inline-block div.group.flex.items-center.justify-center.w-8.h-8.mr-1::before {
    content: "行" !important;
