/* --- 5. 交互与动效 --- */
@keyframes tasselSwing {
    0%, 100% { transform: translateX(-50%) rotate(-8deg); }
    50% { transform: translateX(-50%) rotate(8deg); }
}

#ai-send-button:hover {
    transform: translateY(-5px) !important;
}

/* 移除所有干扰背景 */
.hover\:bg-\[\#EBF5FF\]:hover, 
.bg-black:hover,
.group:hover {
    background-color: transparent !important;
}

/* --- 6. 移动端适配 --- */
@media (max-width: 768px) {
    #ai-send-button {
        width: 68px !important;
    }
    #ai-send-button::before {
        width: 62px !important;
    }
    div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer {
        height: 60px !important;
        width: 22px !important;
    }
    div.group.flex.items-center.justify-center.w-8.h-8.rounded-full.bg-black.cursor-pointer::before {
        height: 55px !important;
        width: 14px !important;
    }
}
/* ================================================= */
/* == 修复：精准移除气泡顶部红蓝线 == */
/* ================================================= */
/* 锁定宽度 94% 且高度 0.5 (h-0.5) 的绝对定位装饰线 */
div.absolute.top-0.w-\[94\%\].h-0\.5.rounded-xl {
    display: none !important;
    visibility: hidden !important;
    height: 0 !important;
    background: transparent !important;
}
/* ================================================= */
/* == 修复：侧边栏层级穿透 (确保在牌匾导航栏之上) == */
/* ================================================= */

/* 1. 给顶部导航栏(牌匾)设置一个较低的基础层级 */
.sticky.top-0.flex.h-12, 
.sticky.top-0.flex.h-16 {
    z-index: 1 !important; /* 降低导航栏层级 */
}

/* 2. 极端提升侧边栏容器的层级 */
/* 无论是折叠还是展开，都必须在导航栏之上 */
.chat-container > div > div:last-child .markdown-body details {
    z-index: 9999 !important; /* 提升至近万级 */
}

/* 3. 展开状态的侧边栏需要更高，确保它在所有元素最前方 */
.chat-container > div > div:last-child .markdown-body details[open] {
    z-index: 10000 !important; 
}

/* 33. 确保侧边栏内的悬浮提示(Tooltip)也在最顶层 */
.chat-container  > div  >  div:last-child .markdown-body details[open] span[title]:hover::after {
    z-index: 10002 !important;
}

/* 4. 修复：如果侧边栏依然被遮挡，可能是父级容器限制了层级 */
/* 强制侧边栏所在的 Markdown 容器不裁剪溢出 */
.chat-container > div > div:last-child .markdown-body {
    overflow: visible !important;
    z-index: 9999 !important;
}
/* 增强展开状态的浮空感，视觉上进一步压制导航栏 */
.chat-container > div > div:last-child .markdown-body details[open] {
    box-shadow: -15px 15px 40px rgba(0, 0, 0, 0.6), 
                0 0 0 1px rgba(197, 160, 89, 0.3) !important;
}

/* ================================================= */
/* == 模块二十五：数值状态条 (极简高亮版) == */
/* ================================================= */

/* 1. 基础重置：让 code 标签回归本质，不再像个大黑盒子 */
.markdown-body details[open] code,
.chat-container > div > div:last-child .markdown-body details[open] code {
    all: unset !important; /* 彻底清除之前的深色背景和边框 */
    display: inline !important; /* 回归行内显示 */
    font-family: 'Consolas', 'Monaco', 'Courier New', monospace !important;
    font-size: 1.1em !important;
    font-weight: 900 !important; /* 加粗条形符号 */
    letter-spacing: 0px !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* 2. 【血气】渲染：针对第一个 code 及其所在行 */
/* 效果：让 [▓▓▓▓▓░░░░░] 呈现鲜血欲滴的质感 */
.markdown-body details[open] code:nth-of-type(1),
.chat-container > div > div:last-child .markdown-body details[open] code:nth-of-type(1) {
    color: #FF3030 !important; /* 纯正血红色 */
    /* 利用多重阴影让 ▓ 更有实体感，而不模糊 */
    text-shadow: 
        1px 1px 0px rgba(0,0,0,0.2),
        0 0 8px rgba(255, 48, 48, 0.4) !important;
}

/* 3. 【元气】渲染：针对第二个 code 及其所在行 */
/* 效果：让 [▓▓▓▓▓░░░░░] 呈现灵力波动的湛蓝感 */
.markdown-body details[open] code:nth-of-type(2),
.chat-container > div > div:last-child .markdown-body details[open] code:nth-of-type(2) {
    color: #1E90FF !important; /* 灵力蓝色 */
    text-shadow: 
        1px 1px 0px rgba(0,0,0,0.2),
        0 0 8px rgba(30, 144, 255, 0.4) !important;
}

/* 4. 符号增强：让已满的 ▓ 更有光泽，未满的 ░ 呈半透明 */
/* 注意：此部分仅能通过颜色整体控制 */
.markdown-body details[open] code {
    -webkit-font-smoothing: antialiased;
    padding: 0 2px !important;
}

/* 5. 针对数字部分的“染色”方案 */
/* 由于数字在 code 之外，我们通过给父级段落设置一个微妙的颜色引导 */
.markdown-body details[open] p {
    /* 确保文字和 code 对齐 */
    line-height: 1.6 !important;
}

/* 6. 侧边栏宽度适配：防止在窄屏下换行 */
.chat-container > div > div:last-child .markdown-body details[open] code {
    white-space: nowrap !important;
}

/* ================================================= */
/* == 进阶：如果你能让 AI 输出时把数字也包进 code 里 == */
/* == 那么下面的代码会让数字也彻底变红/变蓝 == */
/* ================================================= */
/* 如果 AI 输出是 <code>[▓▓▓] {6500}</code> */
.markdown-body details[open] code:nth-of-type(1) {
    background: rgba(255, 48, 48, 0.05) !important; /* 极淡的红晕背景 */
    padding: 2px 4px !important;
    border-radius: 3px !important;
}

.markdown-body details[open] code:nth-of-type(2) {
    background: rgba(30, 144, 255, 0.05) !important; /* 极淡的蓝晕背景 */
    padding: 2px 4px !important;
    border-radius: 3px !important;
}

/* ================================================= */
/* == 原平台追加补丁：高级覆盖层 · 思维链 / 章节框 / 天机选项 == */
/* == 直接放在原 CSS 最末尾，不要放前面 == */
/* ================================================= */

/* ================================================= */
/* == 0. 补充主题变量：仅供本补丁使用 == */
/* ================================================= */

:root {
    --sh-paper: #fcfaf2;
    --sh-paper-rgb: 252, 250, 242;
    --sh-paper-deep: #f3e9d2;
    --sh-paper-deep-rgb: 243, 233, 210;
    --sh-ivory: #fdf5e6;
    --sh-ivory-rgb: 253, 245, 230;
    --sh-ink: #2c241b;
    --sh-ink-soft: #3a3226;
    --sh-wood: #5d4037;
    --sh-wood-dark: #2c241b;
    --sh-gold: #c5a059;
    --sh-gold-light: #d4b170;
    --sh-red: #8B0000;
    --sh-blue: #005f9e;
    --sh-green: #228B22;
}

/* ================================================= */
/* == 1. 思维链密卷：只锁定“章节框前的第一个 details” == */
/* == 关键：不会影响主角信息、互动角色等状态栏 == */
/* ================================================= */

/*
    识别逻辑：
    .markdown-body > details:first-of-type:has(~ .chapter-box)

    含义：
    1. 必须是 markdown-body 直接子级的第一个 details；
    2. 它后面必须存在 .chapter-box；
    3. 这通常就是“思维链”折叠栏。

    所以：
    - 当前 AI 气泡里：思维链不会变侧边栏；
    - 后面的主角信息等仍然按你的原侧边栏逻辑走；
    - 历史气泡里如果没有这种结构，不会被误伤。
*/

.markdown-body > details:first-of-type:has(~ .chapter-box),
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box),
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] {
    /* 彻底解除原侧边栏 fixed 影响 */
    position: relative !important;
    inset: auto !important;
    top: auto !important;
    right: auto !important;
    bottom: auto !important;
    left: auto !important;

    display: block !important;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    height: auto !important;
    max-height: none !important;

    margin: 0 0 18px 0 !important;
    padding: 0 !important;

    overflow: hidden !important;
    overflow-x: hidden !important;
    overflow-y: hidden !important;

    background:
        linear-gradient(135deg, rgba(44,36,27,0.92), rgba(93,64,55,0.88)),
        radial-gradient(circle at 15% 20%, rgba(197,160,89,0.22), transparent 38%) !important;
    border: 1px solid rgba(212,177,112,0.78) !important;
    border-radius: 14px !important;

    box-shadow:
        0 10px 28px rgba(44,36,27,0.24),
        inset 0 0 24px rgba(255,255,255,0.05),
        inset 0 0 0 1px rgba(255,255,255,0.08) !important;

    z-index: 18 !important;
    transform: none !important;
    transition: all 0.22s ease !important;
    box-sizing: border-box !important;
}

/* 密卷内边框 */
.markdown-body > details:first-of-type:has(~ .chapter-box)::before,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)::before {
    content: "" !important;
    position: absolute !important;
    inset: 1px !important;
    border-radius: 13px !important;
    border: 1px solid rgba(255,245,210,0.16) !important;
    pointer-events: none !important;
    z-index: 0 !important;
}

/* 密卷暗纹字 */
.markdown-body > details:first-of-type:has(~ .chapter-box)::after,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)::after {
    content: "玄" !important;
    position: absolute !important;
    right: 18px !important;
    top: 50% !important;
    transform: translateY(-50%) rotate(-10deg) !important;
    font-family: 'LiSu', 'STXingkai', serif !important;
    font-size: 42px !important;
    color: rgba(212,177,112,0.13) !important;
    pointer-events: none !important;
    z-index: 0 !important;
}

/* 思维链 summary：解除侧边栏竖排影响 */
.markdown-body > details:first-of-type:has(~ .chapter-box) > summary,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) > summary,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > summary {
    position: relative !important;
    top: auto !important;

    min-height: 48px !important;
    width: 100% !important;
    max-width: 100% !important;

    padding: 12px 52px 12px 18px !important;
    margin: 0 !important;

    list-style: none !important;
    cursor: pointer !important;

    writing-mode: horizontal-tb !important;
    text-orientation: mixed !important;
    white-space: normal !important;
    overflow: visible !important;
    text-overflow: clip !important;

    display: flex !important;
    align-items: center !important;
    justify-content: flex-start !important;

    background:
        linear-gradient(90deg, rgba(139,0,0,0.58), rgba(197,160,89,0.20), transparent),
        linear-gradient(180deg, rgba(255,255,255,0.08), transparent) !important;

    color: #f8ead0 !important;
    border: none !important;
    border-radius: 14px !important;

    font-family: 'LiSu', 'STXingkai', 'Kaiti SC', serif !important;
    font-size: 1.12em !important;
    font-weight: 700 !important;
    letter-spacing: 2px !important;
    line-height: 1.35 !important;
    text-align: left !important;

    text-shadow:
        0 1px 0 rgba(0,0,0,0.45),
        0 0 12px rgba(212,177,112,0.35) !important;

    box-shadow: none !important;
    z-index: 2 !important;
}

/* 隐藏默认 marker */
.markdown-body > details:first-of-type:has(~ .chapter-box) > summary::-webkit-details-marker,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) > summary::-webkit-details-marker {
    display: none !important;
}

/* 左侧菱形 */
.markdown-body > details:first-of-type:has(~ .chapter-box) > summary::before,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) > summary::before {
    content: "◈" !important;
    position: static !important;
    display: inline-block !important;

    width: auto !important;
    height: auto !important;
    margin: 0 10px 0 0 !important;

    background: none !important;
    color: var(--sh-gold-light) !important;

    font-size: 0.95em !important;
    line-height: 1 !important;
}

/* 右侧密卷标 */
.markdown-body > details:first-of-type:has(~ .chapter-box) > summary::after,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) > summary::after {
    content: "密卷" !important;
    position: absolute !important;
    right: 16px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;

    padding: 2px 8px !important;
    border: 1px solid rgba(212,177,112,0.62) !important;
    border-radius: 999px !important;

    color: rgba(253,245,230,0.9) !important;
    background: rgba(44,36,27,0.35) !important;

    font-family: 'Kaiti SC', serif !important;
    font-size: 12px !important;
    letter-spacing: 1px !important;
    line-height: 1.4 !important;
}

/* 未展开 hover */
.markdown-body > details:first-of-type:has(~ .chapter-box):not([open]):hover,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box):not([open]):hover {
    transform: translateY(-1px) !important;
    border-color: rgba(245,213,148,0.95) !important;
    box-shadow:
        0 14px 34px rgba(44,36,27,0.30),
        0 0 0 1px rgba(212,177,112,0.22),
        inset 0 0 28px rgba(255,255,255,0.06) !important;
}

/* 展开后的思维链内容：仍在气泡内，不变侧栏 */
.markdown-body > details:first-of-type:has(~ .chapter-box)[open],
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] {
    width: 100% !important;
    max-width: 100% !important;

    background:
        linear-gradient(180deg, rgba(253,245,230,0.96), rgba(243,233,210,0.96)) !important;
    border-color: rgba(197,160,89,0.82) !important;

    overflow: visible !important;
    overflow-y: visible !important;
    overflow-x: visible !important;

    max-height: none !important;
    scrollbar-width: auto !important;
}

/* 展开后的内容元素 */
.markdown-body > details:first-of-type:has(~ .chapter-box)[open] > p,
.markdown-body > details:first-of-type:has(~ .chapter-box)[open] > div,
.markdown-body > details:first-of-type:has(~ .chapter-box)[open] > ul,
.markdown-body > details:first-of-type:has(~ .chapter-box)[open] > ol,
.markdown-body > details:first-of-type:has(~ .chapter-box)[open] > table,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > p,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > div,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > ul,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > ol,
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box)[open] > table {
    margin: 0 !important;
    padding: 15px 18px !important;
    width: auto !important;
    color: var(--sh-ink) !important;
    background: transparent !important;
    font-family: 'Kaiti SC', 'STKaiti', 'KaiTi', serif !important;
    line-height: 1.75 !important;
    overflow: visible !important;
}

/* ================================================= */
/* == 1.1 如果思维链存在，修正后续侧边栏折叠位置 == */
/* == 避免主角信息因为变成 nth-of-type(2) 而整体下移 == */
/* ================================================= */

/* 桌面端：思维链之后的状态栏重新从第一档开始排 */
.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(2):not([open]) {
    top: 40px !important;
    border-left-color: #8B0000 !important;
}

.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(3):not([open]) {
    top: 180px !important;
    border-left-color: #005f9e !important;
}

.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(4):not([open]) {
    top: 320px !important;
    border-left-color: #c5a059 !important;
}

.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(5):not([open]) {
    top: 460px !important;
    border-left-color: #556b2f !important;
}

.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(6):not([open]) {
    top: 600px !important;
    border-left-color: #800080 !important;
}

.chat-container > div > div:last-child .markdown-body > details:first-of-type:has(~ .chapter-box) ~ details:nth-of-type(7):not([open]) {
    top: 740px !important;
    border-left-color: #800080 !important;
}

/* ================================================= */
/* == 2. 章节框：金纹玉牒，同款高级覆盖 == */
/* ================================================= */

.markdown-body .chapter-box {
    margin: 12px auto 26px auto !important;
    padding: 22px 24px 20px 24px !important;

    background:
        radial-gradient(circle at 12% 18%, rgba(197,160,89,0.18), transparent 32%),
        radial-gradient(circle at 88% 18%, rgba(139,0,0,0.10), transparent 30%),
        linear-gradient(135deg, rgba(253,245,230,0.96), rgba(252,250,242,0.90) 48%, rgba(243,233,210,0.92)) !important;

    border: 1px solid rgba(197,160,89,0.88) !important;
    border-radius: 16px !important;
    outline: none !important;

    box-shadow:
        0 12px 32px rgba(44,36,27,0.16),
        inset 0 0 0 1px rgba(255,255,255,0.62),
        inset 0 0 42px rgba(197,160,89,0.10) !important;

    overflow: hidden !important;
    position: relative !important;

    display: flex !important;
    flex-direction: column !important;
    gap: 10px !important;
}

/* 金纹内框 */
.markdown-body .chapter-box::before {
    content: "" !important;
    position: absolute !important;
    inset: 8px !important;

    border: 1px solid rgba(197,160,89,0.38) !important;
    border-radius: 11px !important;

    pointer-events: none !important;
    z-index: 0 !important;
}

/* 右下印章 */
.markdown-body .chapter-box::after {
    content: "武道纪" !important;
    position: absolute !important;

    bottom: 14px !important;
    right: 18px !important;

    width: 22px !important;
    padding: 6px 4px !important;

    border: 2px solid rgba(139,0,0,0.72) !important;
    color: rgba(139,0,0,0.78) !important;
    background: rgba(253,245,230,0.42) !important;
    border-radius: 4px !important;

    font-size: 11px !important;
    font-family: 'LiSu', 'STXingkai', serif !important;
    line-height: 1.15 !important;
    text-align: center !important;

    opacity: 0.52 !important;
    transform: rotate(-15deg) !important;

    box-shadow: inset 0 0 8px rgba(139,0,0,0.08) !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

.markdown-body .chapter-box > * {
    position: relative !important;
    z-index: 2 !important;
}

.markdown-body .chap-t {
    padding: 0 0 11px 0 !important;
    margin-bottom: 8px !important;

    color: #7d0000 !important;
    border-bottom: 1px solid rgba(197,160,89,0.52) !important;

    font-family: 'LiSu', 'STXingkai', 'Kaiti SC', serif !important;
    font-size: 1.38em !important;
    font-weight: bold !important;
    letter-spacing: 1.5px !important;

    text-shadow: 0 1px 0 rgba(255,255,255,0.78) !important;
}

.markdown-body .chap-lo,
.markdown-body .chap-wea {
    padding-left: 12px !important;
    border-left: 3px solid rgba(197,160,89,0.54) !important;

    color: #3a2d22 !important;

    font-family: 'Kaiti SC', 'STKaiti', 'KaiTi', serif !important;
    font-size: 1.05em !important;
    line-height: 1.65 !important;
}

.markdown-body .chap-th {
    margin-top: 8px !important;
    padding: 6px 13px !important;
    width: fit-content !important;

    background:
        linear-gradient(90deg, rgba(139,0,0,0.10), rgba(197,160,89,0.14)) !important;

    border: 1px solid rgba(197,160,89,0.46) !important;
    border-left: 4px solid var(--sh-red) !important;
    border-radius: 999px !important;

    color: #6d3b2c !important;

    font-family: 'Kaiti SC', 'STKaiti', 'KaiTi', serif !important;
    font-size: 0.92em !important;
    font-style: normal !important;
    letter-spacing: 0.5px !important;
}

/* ================================================= */
/* == 3. 天机选项：玉简令牌，同款高级覆盖 == */
/* ================================================= */

.markdown-body .Option {
    display: block !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;

    margin: 24px 0 22px 0 !important;
    padding: 20px 24px 20px 26px !important;

    background:
